const info = JSON.parse(Deno.readTextFileSync('/tmp/probeinfo.json'));
let n=0;
for (const m of info.modules) {
  if (!m.specifier?.includes('skmtc')) continue;
  const rel = m.specifier.replace('https://jsr.io/','');
  const dest = '/tmp/skmtcsrc/'+rel;
  if (!m.local) continue;
  try {
    Deno.mkdirSync(dest.split('/').slice(0,-1).join('/'), {recursive:true});
    Deno.copyFileSync(m.local, dest); n++;
  } catch(e) { console.log('ERR', rel, e.message) }
}
console.log('copied', n);
"

