  override toString(): string {
    const { type, name, typeName } = this.identifier
    const exportPrefix = this.noExport ? '' : 'export '
    const keyword = toTsKeyword(type)

    const leadingComment = this.leadingComment
      ? this.leadingComment
          .split('\n')
          .map(line => `// ${line}\n`)
          .join('')
