import {
  emptyEnrichmentSchema,
  toRefName,
  type CustomValue,
  type EmptyEnrichments,
  type GenerateContextType,
  type ModelProjectionConstructorArgs,
  type OasObject,
  type OasRef,
  type OasSchema,
  type RefName,
  type Stringable
} from '@skmtc/core'
import { sanitizePropertyName, toTsModelProjectionBase } from '@skmtc/lang-typescript'
import { effectModule, generatorId, schemaNamespace } from './constants.ts'
import { toSchemaExportPath, toSchemaName } from './naming.ts'

/** Anything that can appear in a property slot of a parsed OAS object. */
type SchemaNode = OasSchema | OasRef<'schema'> | CustomValue

/**
 * Ref names whose projection is mid-construction, per generate context.
 *
 * A `$ref` back to a name already on this stack is a cycle: re-entering
 * `insertModel` would recurse forever (the Driver only caches a definition
 * *after* the projection constructor returns), so those edges render as a
 * lazy `Schema.suspend(...)` instead.
 */
const inFlightByContext = new WeakMap<GenerateContextType, Set<RefName>>()

const toInFlight = (context: GenerateContextType): Set<RefName> => {
  const existing = inFlightByContext.get(context)

  if (existing) {
    return existing
  }

  const created = new Set<RefName>()
  inFlightByContext.set(context, created)

  return created
}

/** Indents every line but the first — used when nesting a rendered value. */
const indent = (value: Stringable): string => value.toString().split('\n').join('\n  ')

const toLiteralArgs = (values: readonly (string | number | boolean | null)[]): string =>
  values.map(value => (typeof value === 'string' ? `'${value}'` : String(value))).join(', ')

const base = toTsModelProjectionBase<EmptyEnrichments>({
  id: generatorId,
  toIdentifierName: ({ refName }) => toSchemaName(refName),
  toIdentifierType: () => ({ type: 'variable' }),
  toExportPath: ({ refName }) => toSchemaExportPath(refName),
  toEnrichmentSchema: () => emptyEnrichmentSchema
})

/**
 * The effect `Schema` value for one OpenAPI model — rendered as the
 * right-hand side of `export const <Name> = ...`.
 *
 * Every `$ref` edge is delegated to a peer projection through `insertModel`,
 * so a referenced model is defined exactly once in its own file and imported
 * where it is used.
 */
export class EffectSchema extends base {
  value: Stringable

  constructor(args: ModelProjectionConstructorArgs<EmptyEnrichments>) {
    super(args)

    this.register({ imports: { [effectModule]: [schemaNamespace] } })

    const inFlight = toInFlight(this.context)
    inFlight.add(this.refName)

    try {
      this.value = this.toValue(this.context.resolveSchemaRefOnce(this.refName, generatorId))
    } finally {
      inFlight.delete(this.refName)
    }
  }

  override toString(): string {
    return this.value.toString()
  }

  /** Renders one schema node, wrapping in `Schema.NullOr` when nullable. */
  private toValue(schema: SchemaNode): Stringable {
    const value = this.toUnwrappedValue(schema)

    return 'nullable' in schema && schema.nullable === true
      ? `${schemaNamespace}.NullOr(${value})`
      : value
  }

  private toUnwrappedValue(schema: SchemaNode): Stringable {
    switch (schema.type) {
      case 'custom':
        return schema.value
      case 'ref':
        return this.toRefValue(toRefName(schema.$ref))
      case 'object':
        return this.toStructValue(schema)
      case 'array':
        return `${schemaNamespace}.Array(${indent(this.toValue(schema.items))})`
      case 'union':
        return `${schemaNamespace}.Union(${schema.members
          .map(member => indent(this.toValue(member)))
          .join(', ')})`
      case 'string':
        return schema.enums?.length
          ? `${schemaNamespace}.Literal(${toLiteralArgs(schema.enums)})`
          : `${schemaNamespace}.String`
      case 'integer':
      case 'number':
        return schema.enums?.length
          ? `${schemaNamespace}.Literal(${toLiteralArgs(schema.enums)})`
          : `${schemaNamespace}.Number`
      case 'boolean':
        return `${schemaNamespace}.Boolean`
      case 'void':
        return `${schemaNamespace}.Void`
      default:
        return `${schemaNamespace}.Unknown`
    }
  }

  private toStructValue(schema: OasObject): Stringable {
    const { properties, required } = schema

    const entries = Object.entries(properties ?? {}).map(([name, property]) => {
      const value = this.toValue(property)
      const wrapped = required?.includes(name)
        ? value
        : `${schemaNamespace}.optional(${value.toString()})`

      return indent(`${sanitizePropertyName(name)}: ${wrapped}`)
    })

    return entries.length
      ? `${schemaNamespace}.Struct({\n  ${entries.join(',\n  ')}\n})`
      : `${schemaNamespace}.Struct({})`
  }

  /**
   * Renders a `$ref` edge. The common case delegates to `insertModel`, which
   * materialises the peer's definition in its own file and stitches the
   * import into this one. A ref that closes a cycle is emitted as a
   * `Schema.suspend` thunk — the binding it names is only read lazily, so the
   * peer needs no import when it lives in this same file (self-recursion) and
   * a plain one when it does not.
   */
  private toRefValue(refName: RefName): Stringable {
    if (!toInFlight(this.context).has(refName)) {
      return this.insertModel(EffectSchema, refName).toName()
    }

    const settings = this.context.toModelContentSettings({ refName, projection: EffectSchema })
    const name = settings.identifier.name

    // `register` drops self-imports, so the self-recursive case is a no-op.
    this.register({ imports: { [settings.exportPath]: [name] } })

    return `${schemaNamespace}.suspend((): ${schemaNamespace}.Schema<any> => ${name})`
  }
}

