    inFlight.add(this.refName)

    try {
      this.value = toEffectValue(context.resolveSchemaRefOnce(this.refName, generatorId), {
        context,
        destinationPath
      })
    } finally {
      inFlight.delete(this.refName)
    }
  }

  override toString(): string {
    return this.value.toString()
  }
}
